const translationAliases: Record<string, string> = {
  libraryTitle1: "articleTitle1",
  libraryTitle2: "articleTitle2",
  libraryTitle3: "articleTitle3",
  libraryCopy1: "articleCopy1",
  libraryCopy2: "articleCopy2",
  libraryCopy3: "articleCopy3",
};

function applyLanguage(lang: LanguageCode) {
  document.documentElement.lang = lang;
  document.querySelectorAll<HTMLElement>("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n || "";
    const original = element.dataset.i18nOriginal || element.textContent || "";
    if (!element.dataset.i18nOriginal) element.dataset.i18nOriginal = original;
    const alias = translationAliases[key];
    const translated = lang === "en"
      ? original
      : generatedCopy[lang]?.[key]
        || copy[lang][key]
        || sharedCopy[lang][key]
        || (alias ? generatedCopy[lang]?.[alias] || copy[lang][alias] || sharedCopy[lang][alias] : "")
        || original;
    if (element.textContent !== translated) element.textContent = translated;
  });
  document.querySelectorAll<HTMLInputElement>("[data-i18n-placeholder]").forEach((input) => {
    const key = input.dataset.i18nPlaceholder || "";
    const original = input.dataset.i18nOriginalPlaceholder || input.placeholder;
    if (!input.dataset.i18nOriginalPlaceholder) input.dataset.i18nOriginalPlaceholder = original;
    const translated = lang === "en"
      ? original
      : generatedCopy[lang]?.[key] || copy[lang][key] || sharedCopy[lang][key] || original;
    if (input.placeholder !== translated) input.placeholder = translated;
  });
}

