export function LanguageSwitcher() {
  const [open, setOpen] = useState(false);
  const [language, setLanguage] = useState<LanguageCode>("en");
  const root = useRef<HTMLDivElement>(null);
  const languageRef = useRef<LanguageCode>("en");

  useEffect(() => {
    const saved = localStorage.getItem("superbuy-sheet-language") as LanguageCode | null;
    const requested = new URLSearchParams(window.location.search).get("lang") as LanguageCode | null;
    const initial = languages.some((item) => item.code === requested) ? requested! : languages.some((item) => item.code === saved) ? saved! : "en";
    languageRef.current = initial;
    const languageTimer = window.setTimeout(() => setLanguage(initial), 0);
    applyLanguage(initial);
    const observer = new MutationObserver(() => applyLanguage(languageRef.current));
    observer.observe(document.body, { childList: true, subtree: true });
    const close = (event: MouseEvent) => { if (root.current && !root.current.contains(event.target as Node)) setOpen(false); };
    document.addEventListener("click", close);
    return () => {
      window.clearTimeout(languageTimer);
      observer.disconnect();
      document.removeEventListener("click", close);
    };
  }, []);

  function choose(code: LanguageCode) {
    languageRef.current = code;
    setLanguage(code);
    setOpen(false);
    localStorage.setItem("superbuy-sheet-language", code);
    const url = new URL(window.location.href);
    if (code === "en") url.searchParams.delete("lang"); else url.searchParams.set("lang", code);
    window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}`);
    applyLanguage(code);
  }

  const active = languages.find((item) => item.code === language)!;
  const labels = menuCopy[language];
  return (
    <div className="language-switcher" ref={root}>
      <button className="language-button" type="button" onClick={() => setOpen((value) => !value)} aria-expanded={open} aria-label="Change language">
        <span>{language.toUpperCase()}</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m6 8 4 4 4-4" /></svg>
      </button>
      {open && <div className="language-menu">
        <div className="language-menu-title">{labels.title} <small>{labels.subtitle}</small></div>
        {languages.map((item) => <button type="button" key={item.code} onClick={() => choose(item.code)} className={item.code === language ? "active" : ""}><span>{item.label}<small>{item.countries}</small></span><b>{item.code.toUpperCase()}</b></button>)}
        <p>{labels.note}</p>
      </div>}
      <span className="sr-only" aria-live="polite">{labels.current}: {active.label}</span>
    </div>
  );
}
